// Refreshes the checked-in OpenUI artifacts from the pinned devDependencies:
//   vendor/openui-bundle.min.js, vendor/openui-styles.css — the prebuilt renderer
//   vendor/openui-dark.css — the library's dark theme as body.openui-dark variables
//   skills/openui/reference.md — the component reference generated by the library
// Run with `npm run vendor` after bumping @openuidev/* versions.
import { copyFileSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { createRequire } from "node:module";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const require = createRequire(import.meta.url);
const bundleDir = join(dirname(require.resolve("@openuidev/browser-bundle/package.json")), "dist");
const bundleVersion = JSON.parse(
  readFileSync(join(bundleDir, "..", "package.json"), "utf8"),
).version;

mkdirSync(join(root, "vendor"), { recursive: true });
copyFileSync(join(bundleDir, "openui-bundle.min.js"), join(root, "vendor/openui-bundle.min.js"));
copyFileSync(join(bundleDir, "openui-styles.css"), join(root, "vendor/openui-styles.css"));

const ui = await import("@openuidev/react-ui");
const kebab = (key) =>
  key
    .replace(/([a-z])([A-Z])/g, "$1-$2")
    .replace(/([A-Z])([A-Z])/g, "$1-$2")
    .replace(/([a-z])(\d)/g, "$1-$2")
    .toLowerCase();
const darkVars = Object.entries(ui.defaultDarkTheme)
  .filter(([, value]) => typeof value === "string")
  .map(([key, value]) => `  --openui-${kebab(key)}: ${value};`)
  .join("\n");
writeFileSync(join(root, "vendor/openui-dark.css"), `body.openui-dark {\n${darkVars}\n}\n`);

const lib = await import("@openuidev/react-ui/genui-lib");
const prompt = lib.openuiChatLibrary.prompt(lib.openuiChatPromptOptions);
writeFileSync(
  join(root, "skills/openui/reference.md"),
  `# OpenUI Lang reference\n\nGenerated from @openuidev/react-ui openuiChatLibrary (browser-bundle ${bundleVersion}).\n` +
    `It was written as a chat system prompt: wherever it says "your response", read "the .oui file".\n\n---\n\n${prompt}\n`,
);
console.log(`vendored @openuidev/browser-bundle ${bundleVersion}`);
